/* Order presentation only. Status labels are localized; financial values and links stay intact. */
(function () {
    'use strict';
    var TABLE_SELECTOR = '.content .grid-view > table.table'; // Original Yii orders grid.
    var IS_STATIC_PREVIEW = !!document.querySelector('script[src="assets/preview-only.js"]'); // Never navigate the preview to live endpoints.
    var CREDIT_SCALE = 100n; // Sum in hundredths without floating-point errors.
    var COLUMN_KEYS = ['user', 'guid', 'amount', 'price', 'date', 'status', 'payment', 'actions']; // Original order, unchanged.
    var COPY_FEEDBACK_MS = 3200; // Lifetime of the fixed clipboard notification.
    var STATUS_DEFINITIONS = { // Display catalog; planned states require backend integration before filtering.
        NEW: { label: 'Новый', className: 'label-default' },
        IN_PROGRESS: { label: 'В обработке', className: 'label-info' },
        COMPLETED: { label: 'Оплачен', className: 'label-success' },
        CANCELLED: { label: 'Отменён', className: 'label-default' },
        FAILED: { label: 'Ошибка платежа', className: 'label-danger', planned: true },
        DECLINED: { label: 'Отклонён', className: 'label-danger', planned: true },
        EXPIRED: { label: 'Истёк', className: 'label-warning', planned: true }
    };
    var LEGACY_STATUS_LABELS = { 'Завершено': 'COMPLETED', 'Отменено': 'CANCELLED' }; // Known labels in the original Yii snapshot only.
    var copyFeedbackTimer;

    function statusDefinition(code) {
        return Object.prototype.hasOwnProperty.call(STATUS_DEFINITIONS, code) ? STATUS_DEFINITIONS[code] : null;
    }

    function renderStatus(cell, code) {
        var definition = statusDefinition(code);
        if (!cell || !definition) return false;
        var badge = cell.querySelector('.label');
        if (!badge) {
            badge = document.createElement('span');
            cell.replaceChildren(badge);
        }
        badge.className = 'label ' + definition.className;
        badge.textContent = definition.label;
        cell.dataset.orderStatus = code;
        return true;
    }

    function initStatuses(table) {
        if (!table) return;
        table.querySelectorAll('tbody .order-col-status').forEach(function (cell) {
            var code = cell.getAttribute('data-order-status') || cell.closest('tr').getAttribute('data-order-status');
            if (!code) {
                var text = cell.textContent.trim();
                if (statusDefinition(text)) code = text;
                else if (Object.prototype.hasOwnProperty.call(LEGACY_STATUS_LABELS, text)) code = LEGACY_STATUS_LABELS[text];
                else code = Object.keys(STATUS_DEFINITIONS).find(function (key) { return STATUS_DEFINITIONS[key].label === text; });
            }
            // Unknown provider states remain visible; never infer a financial state from its color.
            renderStatus(cell, code);
        });
        var select = table.querySelector('.filters .order-col-status select[name="status"]');
        if (!select) return;
        var plannedReady = IS_STATIC_PREVIEW || table.dataset.paymentStatusesReady === 'true';
        Object.keys(STATUS_DEFINITIONS).forEach(function (code) {
            var definition = STATUS_DEFINITIONS[code];
            if (definition.planned && !plannedReady) return;
            var option = Array.from(select.options).find(function (item) { return item.value === code; });
            if (option) option.textContent = definition.label;
            else select.appendChild(new Option(definition.label, code));
        });
        // Refresh Select2's label without firing the host's server-filter change handler.
        if (window.jQuery && window.jQuery(select).data('select2')) window.jQuery(select).trigger('change.select2');
    }

    function notifyCopy(message) {
        if (IS_STATIC_PREVIEW) {
            document.dispatchEvent(new CustomEvent('admin:previewnotice', { detail: { message: message } }));
            return;
        }
        var feedback = document.getElementById('orderCopyFeedback');
        if (!feedback) {
            feedback = document.createElement('div');
            feedback.id = 'orderCopyFeedback';
            feedback.className = 'order-copy-feedback';
            feedback.setAttribute('role', 'status');
            document.body.appendChild(feedback);
        }
        feedback.textContent = message;
        feedback.hidden = false;
        clearTimeout(copyFeedbackTimer);
        copyFeedbackTimer = setTimeout(function () { feedback.hidden = true; }, COPY_FEEDBACK_MS);
    }

    function initGuidCopy(table) {
        table.querySelectorAll('tbody .order-col-guid').forEach(function (cell) {
            var code = cell.querySelector('code');
            if (!code || !code.textContent.trim()) return;
            code.title = code.textContent.trim();
            if (cell.querySelector('.js-order-guid-copy')) return;
            var wrapper = document.createElement('span');
            wrapper.className = 'order-guid-value';
            code.before(wrapper);
            wrapper.appendChild(code);
            var button = document.createElement('button');
            button.type = 'button';
            button.className = 'order-guid-copy js-order-guid-copy';
            button.title = 'Копировать GUID';
            button.setAttribute('aria-label', 'Копировать GUID');
            button.innerHTML = '<svg viewBox="0 0 20 20" aria-hidden="true" focusable="false"><rect x="7" y="7" width="10" height="10" rx="2"></rect><path d="M13 7V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h2"></path></svg>';
            wrapper.appendChild(button);
        });
    }

    document.addEventListener('click', async function (event) {
        var button = event.target.closest('.js-order-guid-copy');
        if (!button || button.disabled) return;
        var code = button.closest('.order-col-guid').querySelector('code');
        var guid = code && code.textContent.trim();
        if (!guid) return;
        if (!navigator.clipboard || !navigator.clipboard.writeText) {
            notifyCopy('Копирование недоступно. Выделите GUID и скопируйте вручную.');
            return;
        }
        button.disabled = true;
        try {
            await navigator.clipboard.writeText(guid);
            notifyCopy('GUID скопирован');
        } catch (error) {
            notifyCopy('Не удалось скопировать GUID. Проверьте разрешение браузера.');
        } finally {
            button.disabled = false;
        }
    });

    function creditUnits(cell) {
        if (!cell) return null;
        var raw = cell.getAttribute('data-credit-amount');
        if (raw === null) raw = cell.textContent;
        var match = raw.replace(/\s/g, '').replace(/\u2212/g, '-').match(/^([+-]?)(\d+)(?:[.,](\d{1,2}))?$/);
        if (!match) return null;
        var units = BigInt(match[2]) * CREDIT_SCALE + BigInt((match[3] || '').padEnd(2, '0'));
        return match[1] === '-' ? -units : units;
    }

    function formatCredits(units) {
        var magnitude = units < 0n ? -units : units;
        return (units < 0n ? '−' : units > 0n ? '+' : '') +
            (magnitude / CREDIT_SCALE).toLocaleString('ru-RU') + ',' +
            String(magnitude % CREDIT_SCALE).padStart(2, '0');
    }

    function updateSelectionSummary(table) {
        var summary = table.parentElement.querySelector(':scope > .summary');
        if (!summary) return;
        if (!summary.querySelector('.order-range-summary')) {
            var range = document.createElement('span');
            range.className = 'order-range-summary';
            while (summary.firstChild) range.appendChild(summary.firstChild);
            var result = document.createElement('span');
            result.className = 'order-selection-summary';
            result.setAttribute('role', 'status');
            result.setAttribute('aria-live', 'polite');
            result.setAttribute('aria-atomic', 'true');
            summary.append(range, result);
            var reset = document.createElement('a');
            reset.className = 'order-reset-filters';
            reset.href = window.location.pathname;
            reset.textContent = 'Сбросить фильтр';
            summary.appendChild(reset);
            summary.classList.add('order-summary');
        }
        var selected = Array.from(table.querySelectorAll('tbody .grid-row-check:checked'));
        var total = 0n;
        var invalid = false;
        selected.forEach(function (box) {
            var units = creditUnits(box.closest('tr').querySelector('.order-col-amount'));
            if (units === null) invalid = true;
            else total += units;
        });
        summary.querySelector('.order-range-summary').hidden = selected.length > 0;
        var output = summary.querySelector('.order-selection-summary');
        output.textContent = selected.length ? 'Выбрано: ' + selected.length + ' · ' +
            (invalid ? 'Сумма недоступна: проверьте значения' : 'Итого: ' + formatCredits(total) + ' кредитов') : '';
        output.title = output.textContent;
        output.classList.toggle('has-error', invalid);
    }


    function enhanceOrders() {
        document.querySelectorAll(TABLE_SELECTOR).forEach(function (table) {
            table.classList.add('orders-grid-view');
            Array.from(table.rows).forEach(function (row) {
                var cells = Array.from(row.cells).filter(function (cell) { return !cell.classList.contains('grid-select-cell'); });
                if (cells.length !== COLUMN_KEYS.length) return;
                cells.forEach(function (cell, index) { cell.classList.add('order-col-' + COLUMN_KEYS[index]); });
            });
            var priceHeading = table.querySelector('th.order-col-price a');
            if (priceHeading) priceHeading.textContent = 'Стоимость';
            initStatuses(table);
            initGuidCopy(table);
            updateSelectionSummary(table);
        });
    }
    window.AdminOrderStatus = { init: initStatuses, render: renderStatus };
    document.addEventListener('admin:selectionchange', function (event) {
        if (event.target.matches(TABLE_SELECTOR)) updateSelectionSummary(event.target);
    });
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', enhanceOrders);
    else enhanceOrders();
    if (window.jQuery) window.jQuery(document).on('pjax:end.ordersPresentation', enhanceOrders);
}());

